<?php
require_once __DIR__ . '/../includes/permissions.php';
require_role('student');
$studentStmt = db()->prepare('SELECT id FROM students WHERE user_id=?');
$studentStmt->execute([current_user()['id']]);
$studentId = (int) $studentStmt->fetchColumn();
$stmt = db()->prepare("SELECT ts.teacher_id,ts.subject_id,ts.class_id,c.name AS class_name,c.school_year,s.code AS subject_code,s.name AS subject_name,t.id AS teacher_record_id,u.full_name AS teacher_name,p.id AS period_id,p.name AS period_name,p.ends_at,e.id AS evaluation_id,COUNT(q.id) AS question_count,(SELECT COUNT(*) FROM evaluation_answers ea WHERE ea.evaluation_id=e.id) AS answer_count FROM class_students cs JOIN teacher_subjects ts ON ts.class_id=cs.class_id JOIN classes c ON c.id=ts.class_id JOIN subjects s ON s.id=ts.subject_id JOIN teachers t ON t.id=ts.teacher_id JOIN users u ON u.id=t.user_id JOIN evaluation_periods p ON p.status='open' AND NOW() BETWEEN p.starts_at AND p.ends_at LEFT JOIN evaluations e ON e.student_id=cs.student_id AND e.teacher_id=ts.teacher_id AND e.subject_id=ts.subject_id AND e.class_id=ts.class_id AND e.period_id=p.id LEFT JOIN questions q ON q.is_active=1 WHERE cs.student_id=? GROUP BY ts.teacher_id,ts.subject_id,ts.class_id,c.name,c.school_year,s.code,s.name,t.id,u.full_name,p.id,p.name,p.ends_at,e.id ORDER BY p.ends_at,c.name,s.name,u.full_name");
$stmt->execute([$studentId]);
$assignments = $stmt->fetchAll();
$historyStmt = db()->prepare('SELECT e.submitted_at,p.name period_name,s.name subject_name,c.name class_name,u.full_name teacher_name FROM evaluations e JOIN evaluation_periods p ON p.id=e.period_id JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id JOIN teachers t ON t.id=e.teacher_id JOIN users u ON u.id=t.user_id WHERE e.student_id=? ORDER BY e.submitted_at DESC LIMIT 20');
$historyStmt->execute([$studentId]);
$history = $historyStmt->fetchAll();
$pageTitle = 'Student overview';
require __DIR__ . '/../includes/header.php';
?>
<div class="page-heading"><div><div class="eyebrow">STUDENT WORKSPACE</div><h1>Your voice helps us grow.</h1><p>Share considered feedback about your learning experience. Responses follow your school’s anonymity settings.</p></div></div>
<section class="panel" id="evaluations"><div class="panel-heading"><div><div class="eyebrow">YOUR TASKS</div><h2>Available evaluations</h2></div><span class="pill pill-blue"><?= count(array_filter($assignments, static fn($a) => !$a['evaluation_id'])) ?> pending</span></div><?php if (!$assignments): ?><div class="empty-inline"><span>✦</span><strong>You’re all caught up</strong><p>No evaluation assignments are currently open.</p></div><?php else: ?><div class="assignment-list"><?php foreach ($assignments as $a): $complete = (bool) $a['evaluation_id']; ?><article class="assignment-card"><div class="assignment-mark"><?= $complete ? '✓' : '✦' ?></div><div class="assignment-main"><span class="eyebrow"><?= e($a['period_name']) ?> · <?= e($a['school_year']) ?></span><h3><?= e($a['subject_name']) ?></h3><p><?= e($a['teacher_name']) ?> <span>·</span> <?= e($a['class_name']) ?></p></div><div class="assignment-action"><?php if ($complete): ?><span class="pill pill-green">Completed</span><?php elseif ((int)$a['question_count'] < 1): ?><span class="pill pill-muted">Form unavailable</span><?php else: ?><a class="button button-primary button-small" href="<?= e(url('student/evaluate.php?teacher='.(int)$a['teacher_id'].'&subject='.(int)$a['subject_id'].'&class='.(int)$a['class_id'].'&period='.(int)$a['period_id'])) ?>">Start evaluation →</a><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section>
<section class="panel history-panel"><div class="eyebrow">YOUR HISTORY</div><h2>Recently submitted</h2><?php if (!$history): ?><p class="muted">Completed evaluations will appear here.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Submitted</th><th>Teacher</th><th>Subject</th><th>Period</th></tr></thead><tbody><?php foreach ($history as $item): ?><tr><td><?= e(date('M j, Y',strtotime($item['submitted_at']))) ?></td><td><?= e($item['teacher_name']) ?></td><td><?= e($item['subject_name']) ?><small><?= e($item['class_name']) ?></small></td><td><?= e($item['period_name']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>